ingress.fn:
const v = Number(msg.payload);
if (!isFinite(v)) return null;
return Math.round(v / 2);

// RvcRunMode CurrentMode (cluster 84 attr 1). Convention: mode 0 = Idle, 1 = Cleaning.
const v = Number(msg.payload);
if (!isFinite(v)) return null;
return v === 1;

// Cluster 97 attr 4 (OperationalState enum) → human-readable string.
const v = Number(msg.payload);
if (!isFinite(v)) return null;
const STATES = { 0: 'stopped', 1: 'running', 2: 'paused', 3: 'error', 64: 'seeking_charger', 65: 'charging', 66: 'docked' };
return STATES[v] || `unknown-${v}`;

egress.fn:
// Boolean input toggles RvcRunMode via ChangeToMode command on cluster 84.
// true → mode 1 (Cleaning), false → mode 0 (Idle). Devices with different mode numbering
// need a custom template.
const tm = String(msg.topic || '').match(/^matter\/(\d+)\/(\d+)/);
if (!tm) return null;
const on = !!msg.payload;
msg.payload = {
    nodeId: Number(tm[1]),
    endpoint: Number(tm[2]),
    cluster: 84,
    command: 'ChangeToMode',
    args: { newMode: on ? 1 : 0 }
};
return msg;

// String input triggers RvcOperationalState commands on cluster 97.
// 'pause' → Pause (0), 'resume' → Resume (3), 'dock'/'go_home'/'home' → GoHome (128).
const tm = String(msg.topic || '').match(/^matter\/(\d+)\/(\d+)/);
if (!tm) return null;
const CMD = { pause: 'Pause', resume: 'Resume', dock: 'GoHome', go_home: 'GoHome', home: 'GoHome' };
const cmd = CMD[String(msg.payload || '').toLowerCase()];
if (!cmd) {
    node.warn('Matter RVC Command: unknown value ' + JSON.stringify(msg.payload));
    return null;
}
msg.payload = {
    nodeId: Number(tm[1]),
    endpoint: Number(tm[2]),
    cluster: 97,
    command: cmd,
    args: {}
};
return msg;
